const field=(label,name,value,type='text',extra='')=>`<label class="pe-field">${esc(label)}<input data-field="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,value,values,placeholder)=>`<label class="pe-field">${esc(label)}<select data-field="${name}">${options(values,value,placeholder)}</select></label>`;
const textarea=(label,name,value,rows=5)=>`<label class="pe-field">${esc(label)}<textarea data-field="${name}" rows="${rows}">${esc(value)}</textarea></label>`;
const money=value=>value==null?'':String(Number(value)/100);
const minor=value=>Number.isFinite(Number(value))?Math.round(Number(value)*100):null;
const fail=error=>error?.code==='23505'?'That public profile URL is already taken. Choose another one.':error?.message&&/session/i.test(error.message)?error.message:'We couldn’t save that step. Check your details and try again.';
const blankWorkEntry=()=>({id:null,companyName:'',jobTitle:'',startDate:'',endDate:'',currentlyWorking:false,description:''});
const blankEducationEntry=()=>({id:null,institution:'',qualification:'',fieldOfStudy:'',startYear:'',endYear:''});
const blankLanguageEntry=()=>({originalCode:null,code:'',name:'',proficiency:'professional'});
const collectionField=(label,collection,index,key,value,type='text',extra='')=>`<label class="pe-field">${esc(label)}<input data-collection="${collection}" data-index="${index}" data-key="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const collectionTextarea=(label,collection,index,key,value,rows=3)=>`<label class="pe-field">${esc(label)}<textarea data-collection="${collection}" data-index="${index}" data-key="${key}" rows="${rows}">${esc(value)}</textarea></label>`;
const hasWorkValue=entry=>Boolean(entry.companyName||entry.jobTitle||entry.startDate||entry.endDate||entry.description||entry.currentlyWorking);
const hasEducationValue=entry=>Boolean(entry.institution||entry.qualification||entry.fieldOfStudy||entry.startYear||entry.endYear);
const hasLanguageValue=entry=>Boolean(entry.code||entry.name);

export function validateWorkHistoryEntry(entry){
  if(!hasWorkValue(entry))return null;
  if(!String(entry.companyName||'').trim())return 'Enter the company for each work-history entry.';
  if(!String(entry.jobTitle||'').trim())return 'Enter the job title for each work-history entry.';
  if(!entry.startDate)return 'Choose a start date for each work-history entry.';
  if(!entry.currentlyWorking&&!entry.endDate)return 'Choose an end date or mark the role as current.';
  if(entry.endDate&&entry.endDate<entry.startDate)return 'A work-history end date cannot be before its start date.';
  return null;
}

export function validateEducationEntry(entry){
  if(!hasEducationValue(entry))return null;
  if(!String(entry.institution||'').trim())return 'Enter the institution for each education entry.';
  if(!String(entry.qualification||'').trim())return 'Enter the qualification for each education entry.';
  const startYear=entry.startYear===''?null:Number(entry.startYear),endYear=entry.endYear===''?null:Number(entry.endYear);
  if(startYear!==null&&(!Number.isInteger(startYear)||startYear<1900||startYear>2200))return 'Enter a valid education start year.';
  if(endYear!==null&&(!Number.isInteger(endYear)||endYear<1900||endYear>2200))return 'Enter a valid education end year.';
  if(startYear!==null&&endYear!==null&&endYear<startYear)return 'An education end year cannot be before its start year.';
  return null;
}

export function validateLanguageEntry(entry){
  if(!hasLanguageValue(entry))return null;
  const code=String(entry.code||'').trim().toLowerCase();
  if(!/^[a-z]{2,3}$/.test(code))return 'Use a two- or three-letter language code.';
  if(!String(entry.name||'').trim())return 'Enter the language name.';
  if(!['basic','conversational','professional','native'].includes(entry.proficiency))return 'Choose a valid language proficiency.';
  return null;
}

function showRoot(html){
  if(!root){root=document.createElement('div');root.className='workora-profile-root';document.body.append(root)}
  root.innerHTML=html;
  root.scrollTop=0;
}

export function unmountProfileExperience(){root?.remove();root=null}

async function signedUrl(supabase,bucket,path){if(!path)return null;const {data}=await supabase.storage.from(bucket).createSignedUrl(path,3600);return data?.signedUrl||null}

async function uploadImage({supabase,supabaseUrl,publishableKey,bucket,path,file,onProgress}){
  const {data,error}=await supabase.auth.getSession();
  if(error||!data.session?.access_token)throw new Error('Your session expired. Log in again before uploading.');
  const encoded=path.split('/').map(encodeURIComponent).join('/');
  await new Promise((resolve,reject)=>{
    const request=new XMLHttpRequest();request.open('POST',`${supabaseUrl}/storage/v1/object/${bucket}/${encoded}`);
    request.setRequestHeader('Authorization',`Bearer ${data.session.access_token}`);request.setRequestHeader('apikey',publishableKey);request.setRequestHeader('Content-Type',file.type);request.setRequestHeader('x-upsert','false');
    request.upload.onprogress=event=>event.lengthComputable&&onProgress(Math.round(event.loaded/event.total*100));
    request.onload=()=>request.status>=200&&request.status<300?resolve():reject(new Error('The image could not be uploaded.'));
    request.onerror=()=>reject(new Error('The upload was interrupted.'));
    request.send(file);
  });
}

