function sharedIdentity(state){return `<div class="pe-avatar"><div class="pe-avatar-preview">${state.avatarPreview?`<img src="${esc(state.avatarPreview)}" alt="Profile preview">`:'W'}</div><div><strong>Profile image (optional)</strong><p class="pe-intro">JPG, PNG or WebP · 5 MB maximum</p><label class="pe-file"><input id="pe-avatar-file" type="file" accept="image/jpeg,image/png,image/webp">${state.shared.avatarPath?'Replace image':'Choose image'}</label>${state.shared.avatarPath?'<button class="pe-button" type="button" id="pe-delete-avatar" style="margin-left:8px">Delete image</button>':''}</div></div><div class="pe-grid">${field('Display name','shared.displayName',state.shared.displayName,'text','required')}${select('Country','shared.countryCode',state.shared.countryCode,countries,'Choose a country')}${field('First name','shared.firstName',state.shared.firstName)}${field('Last name','shared.lastName',state.shared.lastName)}${select('Timezone','shared.timezone',state.shared.timezone,timezones,'')}${field('Region or state','shared.region',state.shared.region)}</div>`}
function agreements(state){return `<label class="pe-check"><input data-field="shared.acceptedTerms" type="checkbox" ${state.shared.acceptedTerms?'checked':''}>I agree to the GoWorkora Terms.</label><label class="pe-check"><input data-field="shared.acceptedPrivacy" type="checkbox" ${state.shared.acceptedPrivacy?'checked':''}>I acknowledge the GoWorkora Privacy Policy.</label>`}

