  if(step===3)return `<p class="pe-intro">Choose the areas you hire in and the engagement patterns that best represent your work.</p><div class="pe-grid">${select('Typical project size','client.typicalProjectSize',client.typicalProjectSize,projectSizes,'Choose a project size')}${select('Preferred engagement','client.preferredEngagementType',client.preferredEngagementType,engagementTypes,'Choose an engagement')}</div><div class="pe-options">${HIRING_CATEGORIES.map(category=>`<label class="pe-option ${client.hiringCategories.includes(category)?'selected':''}"><input data-array="hiringCategories" value="${esc(category)}" type="checkbox" ${client.hiringCategories.includes(category)?'checked':''}>${esc(category)}</label>`).join('')}</div>`;
