function renderWorkspace(state,handlers){
  if(state.complete&&!state.editing){showRoot(`${header(state)}<section class="pe-dashboard"><span class="pe-kicker">Profile complete</span><h1>Welcome back, ${esc(state.shared.displayName)}.</h1><p>Your ${esc(state.role)} profile is ready. Keep it current so every new collaboration starts with the right context.</p><div class="pe-stats"><article><span>Completeness</span><h2>100%</h2><p>All required fields are complete.</p></article><article><span>Account</span><h2>${esc(state.role)}</h2><p>${esc(state.role==='client'?(state.client.independentClient?'Independent client':state.client.companyName):state.freelancer.professionalTitle)}</p></article><article><span>Visibility</span><h2>${esc(state.shared.profileVisibility)}</h2><p>Private contact and payment data remain protected.</p></article></div><a class="pe-button dark" href="${state.role==='client'?'#talent':'#jobs'}">${state.role==='client'?'Find talent':'Find work'}</a> ${state.role==='client'?'<a class="pe-button" href="#talent/saved">Saved talent</a> <a class="pe-button" href="#jobs/manage">Manage jobs</a>':'<a class="pe-button" href="#invitations">Invitations</a>'} <a class="pe-button" href="#contracts">Contracts</a> <button class="pe-button" id="pe-edit">Edit profile</button>${state.role==='freelancer'?` <a class="pe-button" href="#freelancers/${esc(state.freelancer.profileSlug)}">Preview public profile</a>`:''}</section>`);bindCommon(handlers);document.querySelector('#pe-edit').onclick=()=>handlers.edit();return}
  const labels=stepsForRole(state.role),progress=onboardingProgress(state.role,state.step,false);
  showRoot(`${header(state)}<section class="pe-shell"><aside class="pe-side"><span class="pe-kicker">${state.complete?'Edit profile':'Set up your profile'}</span><h1>${state.role==='client'?'Tell us how you hire.':'Show clients your best work.'}</h1><div><small>${progress}% complete · Step ${state.step} of ${labels.length}</small><div class="pe-progress"><i style="width:${progress}%"></i></div></div><ol>${labels.map((label,index)=>`<li class="${index+1===state.step?'active':index+1<state.step?'done':''}"><span>${index+1<state.step?'✓':index+1}</span>${esc(label)}</li>`).join('')}</ol></aside><form class="pe-card" id="pe-form"><span class="pe-kicker">Step ${state.step}</span><h2>${esc(labels[state.step-1])}</h2>${state.role==='client'?clientStep(state):freelancerStep(state)}${state.uploadProgress?`<div class="pe-upload"><i style="width:${state.uploadProgress}%"></i>Uploading image… ${state.uploadProgress}%</div>`:''}${state.notice?`<p class="pe-notice" role="status">✓ ${esc(state.notice)}</p>`:''}${state.error?`<p class="pe-error" role="alert">${esc(state.error)}</p>`:''}<div class="pe-actions"><button class="pe-button" id="pe-back" type="button" ${state.step===1||state.saving?'disabled':''}>Back</button><span>Changes save after every step.</span><button class="pe-button dark" type="submit" ${state.saving?'disabled':''}>${state.saving?'Saving…':state.step===labels.length?(state.complete?'Save profile':'Complete profile'):'Save and continue'}</button></div></form></section>`);
  bindCommon(handlers);bindFields(state,handlers);document.querySelector('#pe-form').onsubmit=handlers.submit;document.querySelector('#pe-back').onclick=()=>handlers.back();
}

function bindCommon(handlers){document.querySelector('#pe-home').onclick=handlers.home;document.querySelector('#pe-signout').onclick=handlers.signOut}
function bindFields(state,handlers){
  document.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{const [group,key]=input.dataset.field.split('.');state[group][key]=input.type==='checkbox'?input.checked:input.value;state.error='';if(input.dataset.field==='client.independentClient')renderWorkspace(state,handlers)});
  document.querySelectorAll('[data-array]').forEach(input=>input.onchange=()=>{const target=input.dataset.array==='skillIds'?state.freelancer.skillIds:state.client.hiringCategories;if(input.checked)target.push(input.value);else target.splice(target.indexOf(input.value),1);renderWorkspace(state,handlers)});
  document.querySelectorAll('[data-collection][data-key]').forEach(input=>input.oninput=()=>{const entry=state[input.dataset.collection]?.[Number(input.dataset.index)];if(!entry)return;entry[input.dataset.key]=input.type==='checkbox'?input.checked:input.value;if(input.dataset.key==='currentlyWorking'&&input.checked)entry.endDate='';state.error='';if(input.type==='checkbox')renderWorkspace(state,handlers)});
  document.querySelectorAll('[data-add-collection]').forEach(button=>button.onclick=()=>{const collection=button.dataset.addCollection;if(collection==='workHistory')state.workHistory.push(blankWorkEntry());if(collection==='educationHistory')state.educationHistory.push(blankEducationEntry());if(collection==='languages')state.languages.push(blankLanguageEntry());state.error='';renderWorkspace(state,handlers)});
  document.querySelectorAll('[data-remove-collection]').forEach(button=>button.onclick=()=>{const collection=button.dataset.removeCollection,index=Number(button.dataset.index),entry=state[collection]?.[index];if(!entry)return;if(entry.id){const removed=collection==='workHistory'?state.removedWorkIds:state.removedEducationIds;if(!removed.includes(entry.id))removed.push(entry.id)}if(collection==='languages'&&entry.originalCode&&!state.removedLanguageCodes.includes(entry.originalCode))state.removedLanguageCodes.push(entry.originalCode);state[collection].splice(index,1);state.error='';state.notice='Entry removed from this draft. Save this step to apply the change.';renderWorkspace(state,handlers)});
  document.querySelector('#pe-avatar-file')?.addEventListener('change',event=>{const file=event.target.files?.[0],error=validateProfileUpload(file,'avatar');if(error){state.error=error;renderWorkspace(state,handlers);return}state.avatarFile=file;state.avatarPreview=URL.createObjectURL(file);renderWorkspace(state,handlers)});
  document.querySelector('#pe-company-logo-file')?.addEventListener('change',event=>{const file=event.target.files?.[0],error=validateProfileUpload(file,'avatar');if(error){state.error=error;renderWorkspace(state,handlers);return}state.client.companyLogoFile=file;state.client.companyLogoPreview=URL.createObjectURL(file);renderWorkspace(state,handlers)});
  document.querySelector('#pe-delete-avatar')?.addEventListener('click',()=>handlers.deleteAvatar());
  document.querySelector('#pe-portfolio-file')?.addEventListener('change',event=>{const file=event.target.files?.[0],error=validateProfileUpload(file,'portfolio');if(error){state.error=error;renderWorkspace(state,handlers);return}state.portfolio.file=file;state.portfolio.imagePreview=URL.createObjectURL(file);renderWorkspace(state,handlers)});
  document.querySelector('#pe-delete-portfolio')?.addEventListener('click',()=>handlers.deletePortfolio());
}

async function saveUpload(state,config,kind){
  const file=kind==='avatar'?state.avatarFile:state.portfolio.file;if(!file)return null;
  const bucket=kind==='avatar'?'profile-avatars':'portfolio-assets',path=safeAssetPath(state.user.id,file,kind==='avatar'?'avatar':'portfolio');
  await uploadImage({...config,bucket,path,file,onProgress:value=>{state.uploadProgress=value;renderWorkspace(state,config.handlers)}});
  return path;
}

