async function saveStep(state,config){const {supabase}=config,now=new Date().toISOString();
  if(state.role==='client'){
    const error=validateClientStep(state.step,{...state.shared,...state.client});if(error)throw new Error(error);
    if(state.step===1){await saveShared(state,config);const r=await supabase.from('client_profiles').upsert({user_id:state.user.id,job_title:state.client.jobTitle.trim(),department:state.client.department.trim(),hiring_role:state.client.hiringRole.trim(),language_code:state.client.languageCode},{onConflict:'user_id'});if(r.error)throw r.error}
    if(state.step===2){let companyId=state.client.companyId;if(!state.client.independentClient){const payload={owner_user_id:state.user.id,name:state.client.companyName.trim(),slug:`${normalizeProfileSlug(state.client.companyName)||'company'}-${state.user.id.replaceAll('-','').slice(0,8)}`,website:state.client.companyWebsite.trim()||null,description:state.client.companyDescription.trim(),company_size:state.client.companySize,industry:state.client.industry.trim(),country_code:state.client.companyCountryCode};const result=companyId?await supabase.from('companies').update(payload).eq('id',companyId).select('id').single():await supabase.from('companies').insert(payload).select('id').single();if(result.error)throw result.error;companyId=result.data.id;if(state.client.companyLogoFile){const file=state.client.companyLogoFile,extension=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg',path=`${companyId}/${crypto.randomUUID()}.${extension}`,previous=state.client.companyLogoPath;await uploadImage({...config,bucket:'company-logos',path,file,onProgress:value=>{state.uploadProgress=value;renderWorkspace(state,config.handlers)}});const logoUpdate=await supabase.from('companies').update({logo_path:path}).eq('id',companyId);if(logoUpdate.error){await supabase.storage.from('company-logos').remove([path]);throw logoUpdate.error}if(previous)await supabase.storage.from('company-logos').remove([previous]);state.client.companyLogoPath=path;state.client.companyLogoPreview=supabase.storage.from('company-logos').getPublicUrl(path).data.publicUrl;state.client.companyLogoFile=null}}const r=await supabase.from('client_profiles').upsert({user_id:state.user.id,company_id:state.client.independentClient?null:companyId,independent_client:state.client.independentClient},{onConflict:'user_id'});if(r.error)throw r.error;state.client.companyId=companyId}
    if(state.step===3){const r=await supabase.from('client_profiles').update({hiring_categories:state.client.hiringCategories,typical_project_size:state.client.typicalProjectSize,preferred_engagement_type:state.client.preferredEngagementType}).eq('user_id',state.user.id);if(r.error)throw r.error}
    if(state.step===4){const r=await supabase.from('client_profiles').update({billing_country:state.client.billingCountry,preferred_currency:state.client.preferredCurrency}).eq('user_id',state.user.id);if(r.error)throw r.error}
  }else{
    const error=validateFreelancerStep(state.step,{...state.shared,...state.freelancer,availableCategories:[...new Set(state.skills.map(skill=>skill.category))]});if(error)throw new Error(error);
    if(state.step===1){await saveShared(state,config);const r=await supabase.from('freelancer_profiles').upsert({user_id:state.user.id,professional_title:state.freelancer.professionalTitle.trim(),bio:state.freelancer.bio.trim(),country_code:state.shared.countryCode,timezone:state.shared.timezone,profile_slug:normalizeProfileSlug(state.freelancer.profileSlug)},{onConflict:'user_id'});if(r.error)throw r.error}
    if(state.step===2){const profileUpdate=await supabase.from('freelancer_profiles').update({primary_category:state.freelancer.primaryCategory,years_experience:Number(state.freelancer.yearsExperience)}).eq('user_id',state.user.id);if(profileUpdate.error)throw profileUpdate.error;const existing=await supabase.from('freelancer_skills').select('skill_id').eq('freelancer_user_id',state.user.id);if(existing.error)throw existing.error;const removed=(existing.data||[]).map(item=>item.skill_id).filter(id=>!state.freelancer.skillIds.includes(id));if(removed.length){const r=await supabase.from('freelancer_skills').delete().eq('freelancer_user_id',state.user.id).in('skill_id',removed);if(r.error)throw r.error}const r=await supabase.from('freelancer_skills').upsert(state.freelancer.skillIds.map(skill_id=>({freelancer_user_id:state.user.id,skill_id,proficiency_level:'advanced',years_experience:Number(state.freelancer.yearsExperience)})),{onConflict:'freelancer_user_id,skill_id'});if(r.error)throw r.error}
    if(state.step===3){const r=await supabase.from('freelancer_profiles').update({hourly_rate_minor:minor(state.freelancer.hourlyRate),currency:state.freelancer.currency,experience_level:state.freelancer.experienceLevel,availability_status:state.freelancer.availabilityStatus,weekly_capacity_hours:Number(state.freelancer.weeklyCapacity),minimum_project_minor:state.freelancer.minimumProject?minor(state.freelancer.minimumProject):null}).eq('user_id',state.user.id);if(r.error)throw r.error}
    if(state.step===4)await saveOptionalHistory(state,supabase);
    if(state.step===5)await saveFeaturedPortfolio(state,config);
  }
  if(state.step===stepsForRole(state.role).length){const agreement=await supabase.from('profiles').update({terms_accepted_at:now,privacy_accepted_at:now}).eq('id',state.user.id);if(agreement.error)throw agreement.error;const completed=await supabase.rpc('finalize_profile_onboarding');if(completed.error)throw completed.error;state.complete=true;state.editing=false;state.notice='Your profile is complete and ready to use.';location.hash=roleOnboardingDestination(state.role,true)}
}

async function saveShared(state,config){const {supabase}=config;const r=await supabase.from('profiles').update({display_name:state.shared.displayName.trim(),full_name:state.shared.displayName.trim(),first_name:state.shared.firstName.trim(),last_name:state.shared.lastName.trim(),country_code:state.shared.countryCode||null,timezone:state.shared.timezone,region:state.shared.region.trim()||null,location_visibility:state.shared.locationVisibility,profile_visibility:state.shared.profileVisibility}).eq('id',state.user.id);if(r.error)throw r.error;if(state.avatarFile){const path=await saveUpload(state,config,'avatar'),previous=state.shared.avatarPath;const update=await supabase.from('profiles').update({avatar_path:path}).eq('id',state.user.id);if(update.error)throw update.error;if(previous)await supabase.storage.from('profile-avatars').remove([previous]);state.shared.avatarPath=path;state.avatarFile=null}}
async function saveOptionalHistory(state,supabase){
  for(const entry of state.workHistory){const error=validateWorkHistoryEntry(entry);if(error)throw new Error(error)}
  for(const entry of state.educationHistory){const error=validateEducationEntry(entry);if(error)throw new Error(error)}
  for(const entry of state.languages){const error=validateLanguageEntry(entry);if(error)throw new Error(error)}
  const languageCodes=state.languages.filter(hasLanguageValue).map(entry=>String(entry.code||'').trim().toLowerCase());
  if(new Set(languageCodes).size!==languageCodes.length)throw new Error('Each language code can be added only once.');
  for(const entry of state.workHistory.filter(hasWorkValue)){
    const payload={freelancer_user_id:state.user.id,company_name:entry.companyName.trim(),job_title:entry.jobTitle.trim(),start_date:entry.startDate,end_date:entry.currentlyWorking?null:entry.endDate,currently_working:Boolean(entry.currentlyWorking),description:entry.description.trim()};
    if(entry.id){const result=await supabase.from('work_experience').update(payload).eq('id',entry.id).eq('freelancer_user_id',state.user.id);if(result.error)throw result.error}
    else{const result=await supabase.from('work_experience').insert(payload).select('id').single();if(result.error)throw result.error;entry.id=result.data.id}
  }
  for(const entry of state.educationHistory.filter(hasEducationValue)){
    const payload={freelancer_user_id:state.user.id,institution:entry.institution.trim(),qualification:entry.qualification.trim(),field_of_study:entry.fieldOfStudy.trim(),start_year:entry.startYear===''?null:Number(entry.startYear),end_year:entry.endYear===''?null:Number(entry.endYear)};
    if(entry.id){const result=await supabase.from('education').update(payload).eq('id',entry.id).eq('freelancer_user_id',state.user.id);if(result.error)throw result.error}
    else{const result=await supabase.from('education').insert(payload).select('id').single();if(result.error)throw result.error;entry.id=result.data.id}
  }
  if(state.removedWorkIds.length){const result=await supabase.from('work_experience').delete().eq('freelancer_user_id',state.user.id).in('id',state.removedWorkIds);if(result.error)throw result.error;state.removedWorkIds=[]}
  if(state.removedEducationIds.length){const result=await supabase.from('education').delete().eq('freelancer_user_id',state.user.id).in('id',state.removedEducationIds);if(result.error)throw result.error;state.removedEducationIds=[]}
  if(state.removedLanguageCodes.length){const result=await supabase.from('freelancer_languages').delete().eq('freelancer_user_id',state.user.id).in('language_code',state.removedLanguageCodes);if(result.error)throw result.error;state.removedLanguageCodes=[]}
  for(const entry of state.languages.filter(hasLanguageValue)){
    const normalizedCode=String(entry.code).trim().toLowerCase();
    if(entry.originalCode&&entry.originalCode!==normalizedCode){const removed=await supabase.from('freelancer_languages').delete().eq('freelancer_user_id',state.user.id).eq('language_code',entry.originalCode);if(removed.error)throw removed.error}
    const result=await supabase.from('freelancer_languages').upsert({freelancer_user_id:state.user.id,language_code:normalizedCode,language_name:entry.name.trim(),proficiency_level:entry.proficiency},{onConflict:'freelancer_user_id,language_code'});if(result.error)throw result.error;entry.code=normalizedCode;entry.originalCode=normalizedCode
  }
}
async function saveFeaturedPortfolio(state,config){const {supabase}=config;if(!state.portfolio.title&&!state.portfolio.file)return;if(!state.portfolio.title)throw new Error('Add a title to your portfolio item.');const payload={freelancer_user_id:state.user.id,title:state.portfolio.title,description:state.portfolio.description,project_url:state.portfolio.projectUrl||null,is_published:state.portfolio.isPublished,display_order:0};const r=state.portfolio.id?await supabase.from('portfolio_items').update(payload).eq('id',state.portfolio.id).select('id').single():await supabase.from('portfolio_items').insert(payload).select('id').single();if(r.error)throw r.error;state.portfolio.id=r.data.id;if(state.portfolio.file){const path=await saveUpload(state,config,'portfolio'),previous=state.portfolio.imagePath;const update=await supabase.from('portfolio_items').update({image_path:path}).eq('id',r.data.id);if(update.error)throw update.error;if(previous)await supabase.storage.from('portfolio-assets').remove([previous]);state.portfolio.imagePath=path;state.portfolio.file=null}}

export async function mountPublicFreelancerProfile({supabase,slug,onHome,user,role}){
  showRoot(`<div class="pe-public"><header class="pe-header">${featureBrandLink()}<nav aria-label="Public profile navigation"><a href="/find-talent" data-route="/find-talent">Find talent</a><a href="/find-work" data-route="/find-work">Find work</a><a href="/how-it-works" data-route="/how-it-works">How it works</a></nav></header><div class="pe-empty"><h1>Loading public profile</h1><p>Fetching approved public information only…</p></div></div>`);
  const {data,error}=await supabase.from('freelancer_public_profiles').select('*').eq('profile_slug',normalizeProfileSlug(slug)).maybeSingle();
  if(error||!data?.user_id){
    showRoot(`<div class="pe-public"><header class="pe-header">${featureBrandLink()}<nav aria-label="Public profile navigation"><a href="/find-talent" data-route="/find-talent">Find talent</a><a href="/find-work" data-route="/find-work">Find work</a><a href="/help" data-route="/help">Help Centre</a></nav></header><div class="pe-empty"><h1>Profile not found</h1><p>This profile is private, incomplete, or unavailable.</p><button class="pe-button dark" id="pe-public-home">Explore GoWorkora</button></div></div>`);
    document.querySelector('#pe-public-home').onclick=()=>{unmountProfileExperience();history.replaceState({},'','#top');onHome?.()};
    return;
  }
  const [links,items,workHistory,education,languages,avatar]=await Promise.all([
    supabase.from('freelancer_skills').select('skill_id').eq('freelancer_user_id',data.user_id),
    supabase.from('portfolio_items').select('*').eq('freelancer_user_id',data.user_id).eq('is_published',true).order('display_order'),
    supabase.from('work_experience').select('company_name,job_title,start_date,end_date,currently_working,description').eq('freelancer_user_id',data.user_id).order('start_date',{ascending:false}),
    supabase.from('education').select('institution,qualification,field_of_study,start_year,end_year').eq('freelancer_user_id',data.user_id).order('end_year',{ascending:false}),
    supabase.from('freelancer_languages').select('language_name,proficiency_level').eq('freelancer_user_id',data.user_id).order('language_name'),
    signedUrl(supabase,'profile-avatars',data.avatar_path),
  ]);
  const ids=(links.data||[]).map(item=>item.skill_id);
  const skills=ids.length?(await supabase.from('skills').select('name').in('id',ids)).data||[]:[];
  const portfolio=await Promise.all((items.data||[]).map(async item=>({...item,url:await signedUrl(supabase,'portfolio-assets',item.image_path)})));
  const hireAction=role==='client'?'<button class="pe-button lime" id="pe-contact-talent">Message professional</button>':!user?`<a class="pe-button lime" href="/signup/client?returnTo=${encodeURIComponent(`/find-talent/${data.profile_slug}`)}" data-route="/signup/client">Sign up to hire</a>`:'';
  const professionalMeta=[
    data.primary_category,
    data.years_experience==null?'':`${Number(data.years_experience)} years experience`,
    data.public_location?`◎ ${data.public_location}`:'',
    timezoneOverlapSummary(data.timezone),
  ].filter(Boolean);
  showRoot(`<div class="pe-public"><header class="pe-header">${featureBrandButton('pe-public-home')}<nav aria-label="Public profile navigation"><a href="/find-talent" data-route="/find-talent">Find talent</a><a href="/find-work" data-route="/find-work">Find work</a><a href="/how-it-works" data-route="/how-it-works">How it works</a></nav><button class="pe-button" id="pe-explore-marketplace">Explore marketplace</button></header><article class="pe-public-card"><div class="pe-public-hero"><div class="pe-public-avatar">${avatar?`<img src="${esc(avatar)}" alt="${esc(safePublicDisplayName(data.display_name))} profile">`:'W'}</div><div>${data.is_demo?'<span class="demo-badge">Demo</span>':''}${data.is_verified?'<span class="pe-role">✓ Identity verified</span>':''}<h1>${esc(safePublicDisplayName(data.display_name))}</h1><p>${esc(safePublicProfessionalTitle(data.professional_title))}</p>${data.is_demo?'<p class="demo-disclaimer">Fictional demonstration profile — not a real freelancer or customer.</p>':''}<div class="pe-public-meta">${professionalMeta.map(item=>`<span>${esc(item)}</span>`).join('')}</div></div><div class="pe-public-rate-action"><strong class="pe-rate">${esc(data.currency)} ${esc(money(data.hourly_rate_minor))}/hr</strong>${hireAction}</div></div><div class="pe-public-body"><section><h2>About</h2><p>${esc(data.bio)}</p></section><section><h2>Skills</h2><div class="pe-tags">${skills.map(skill=>`<span>${esc(skill.name)}</span>`).join('')}</div></section>${workHistory.data?.length?`<section><h2>Work history</h2><div class="pe-public-history">${workHistory.data.map(item=>`<article><div><strong>${esc(item.job_title)}</strong><span>${esc(item.company_name)}</span></div><small>${esc(item.start_date)} — ${esc(item.currently_working?'Present':item.end_date||'Not specified')}</small>${item.description?`<p>${esc(item.description)}</p>`:''}</article>`).join('')}</div></section>`:''}${education.data?.length?`<section><h2>Education</h2><div class="pe-public-history">${education.data.map(item=>`<article><div><strong>${esc(item.qualification)}</strong><span>${esc(item.institution)}</span></div><small>${esc([item.field_of_study,item.start_year&&item.end_year?`${item.start_year}–${item.end_year}`:item.end_year||item.start_year].filter(Boolean).join(' · '))}</small></article>`).join('')}</div></section>`:''}${languages.data?.length?`<section><h2>Languages</h2><div class="pe-tags">${languages.data.map(item=>`<span>${esc(item.language_name)} · ${esc(item.proficiency_level)}</span>`).join('')}</div></section>`:''}${portfolio.length?`<section><h2>Portfolio</h2><div class="pe-portfolio">${portfolio.map(item=>`<article>${item.url?`<div class="pe-image"><img src="${esc(item.url)}" alt="${esc(item.title)} project"></div>`:''}<h3>${esc(item.title)}</h3><p>${esc(item.description)}</p></article>`).join('')}</div></section>`:''}</div></article></div>`);
  document.querySelectorAll('#pe-public-home,#pe-explore-marketplace').forEach(button=>button.onclick=()=>{unmountProfileExperience();history.replaceState({},'','#top');onHome?.()});
  document.querySelector('#pe-contact-talent')?.addEventListener('click',()=>openTalentContactDialog({supabase,freelancerUserId:data.user_id,displayName:safePublicDisplayName(data.display_name),professionalTitle:safePublicProfessionalTitle(data.professional_title)}));
}
